</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.util.*;
import java.util.regex.*;

public class TextDoc {

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        scan.nextLine();
        String s = scan.nextLine();

        // Use regex to extract content inside parentheses
        List<String> parenContents = new ArrayList<>();
        Pattern p = Pattern.compile("\\(([^)]*)\\)");
        Matcher m = p.matcher(s);
        while (m.find()) {
            parenContents.add(m.group(1));
        }

        // Find maximum word length and count non-empty words
        int maxLen = 0;
        int wordCount = 0;

        for (String content : parenContents) {
            String[] words = content.split("_");
            for (String word : words) {
                if (!word.isEmpty()) {
                    maxLen = Math.max(maxLen, word.length());
                    wordCount++;
                }
            }
        }

        System.out.println(maxLen + " " + wordCount);
    }
}
